function ContextDrawer({ state, status, onClose }: { state: WorkbenchState; status: BridgeStatus | null; onClose: () => void }) {
  const project = state.projects.find((item) => item.active) || state.projects[0]; const rq = state["research-questions"].find((item) => item.status === "Active") || state["research-questions"][0];
  return <div className="drawer-backdrop" onMouseDown={onClose}><aside className="action-drawer context-drawer" onMouseDown={(e) => e.stopPropagation()}><div className="drawer-head"><button onClick={onClose}>×</button><span className="label">REAL CONTEXT</span><span className="action-mark mint">◇</span></div><div className="drawer-title"><span>KBASE + ZOTERO</span><h2>What WorkBuddy can use now</h2><p>No completeness score is invented. These are the actual connected sources and current records.</p></div><div className="context-groups"><section><div><span>PROJECT FRAME</span><b>{state.projects.length + state["research-questions"].length} records</b></div>{project ? <p><i className="checked">✓</i><span><strong>{project.title}</strong><small>{project.id} · {project.active ? "active" : "first available"}</small></span></p> : <p><i className="warning">!</i><span><strong>No project</strong><small>Create one in Projects</small></span></p>}{rq ? <p><i className="checked">✓</i><span><strong>{rq.title}</strong><small>{rq.id}</small></span></p> : <p><i className="warning">!</i><span><strong>No research question</strong><small>Create one in Research Map</small></span></p>}</section><section><div><span>CONNECTED SOURCES</span><b>Live status</b></div><p><i className={status?.zotero.connected ? "checked" : "warning"}>{status?.zotero.connected ? "✓" : "!"}</i><span><strong>Zotero</strong><small>{status?.zotero.connected ? `Desktop ${status.zotero.version}` : "Offline"}</small></span></p><p><i className={status?.obsidian.connected ? "checked" : "warning"}>{status?.obsidian.connected ? "✓" : "!"}</i><span><strong>Obsidian · {status?.obsidian.vault || "Kbase"}</strong><small>{status?.obsidian.connected ? `${Object.values(state).flat().length} WorkBuddy records` : "Offline"}</small></span></p></section></div><div className="drawer-footer"><span className="small-note">Context is assembled at workflow run time</span><button className="primary-button" onClick={onClose}>Done</button></div></aside></div>;
}

function ActionDrawer({ action, state, onClose, openConnections }: { action: Action; state: WorkbenchState; onClose: () => void; openConnections: () => void }) {
  const [running, setRunning] = useState(false); const [provider, setProvider] = useState<"deepseek" | "kimi">(() => typeof window !== "undefined" && window.localStorage.getItem("workbuddy-ai-provider") === "kimi" ? "kimi" : "deepseek");
  const [input, setInput] = useState(action.label); const [sources, setSources] = useState({ kbase: true, zotero: true, obsidian: true }); const [result, setResult] = useState<WorkflowResult | null>(null); const [error, setError] = useState(""); const [savedPath, setSavedPath] = useState(""); const controller = useRef<AbortController | null>(null);
  useEffect(() => () => controller.current?.abort(), []);
  const run = async () => { if (!input.trim()) return; controller.current?.abort(); const active = new AbortController(); controller.current = active; setRunning(true); setError(""); setResult(null); try { const response = await bridgeFetch(`/ai/run`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ provider, input, command: action.command, sources, projectContext: sources.kbase ? recordContext(state) : "" }), signal: active.signal }); const body = await response.json(); if (!response.ok) throw new Error(body.error || "Workflow failed."); setResult(body); } catch (e) { if (!active.signal.aborted) setError(e instanceof TypeError ? "The local bridge is unreachable or local access is blocked." : e instanceof Error ? e.message : "Workflow failed."); } finally { if (!active.signal.aborted) setRunning(false); } };
  const save = async () => { if (!result) return; try { const evidence = [...result.manifest.zotero.map((item) => `- [${item.id}] ${item.title} — Zotero ${item.key}${item.doi ? ` — DOI ${item.doi}` : ""}`), ...result.manifest.obsidian.map((item) => `- [${item.id}] ${item.title} — ${item.path}`)].join("\n") || "- No external evidence retrieved."; const response = await bridgeFetch(`/obsidian/note`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ title: `${action.command} ${localDateKey(new Date())}`, content: `---\nworkbuddyGenerated: true\nprovider: ${result.provider}\nmodel: ${result.model}\ncreatedAt: ${new Date().toISOString()}\n---\n\n# ${action.label}\n\n${result.output}\n\n## Evidence manifest\n\n${evidence}\n` }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error); setSavedPath(body.path); } catch (e) { setError(e instanceof Error ? e.message : "Could not save to Obsidian."); } };
  return <div className="drawer-backdrop" onMouseDown={onClose}><aside className="action-drawer" role="dialog" aria-modal="true" aria-label={action.label} tabIndex={-1} onMouseDown={(e) => e.stopPropagation()}><div className="drawer-head"><button onClick={onClose}>×</button><span className="label">STRUCTURED AI WORKFLOW</span><span className={`action-mark ${action.tone}`}>✦</span></div><div className="drawer-title"><span>{action.command}</span><h2>{action.label}</h2><p>Selected sources must be retrieved successfully before the model runs.</p></div><div className="provider-switch"><button className={provider === "deepseek" ? "active" : ""} onClick={() => { setProvider("deepseek"); window.localStorage.setItem("workbuddy-ai-provider", "deepseek"); }}><span>DS</span><b>DeepSeek</b><small>V4 Flash</small></button><button className={provider === "kimi" ? "active" : ""} onClick={() => { setProvider("kimi"); window.localStorage.setItem("workbuddy-ai-provider", "kimi"); }}><span>KM</span><b>Kimi</b><small>K3</small></button></div><div className="drawer-section"><div className="drawer-section-title"><span>01</span><strong>Task input</strong><b>Required</b></div><textarea value={input} onChange={(e) => setInput(e.target.value)} /></div><div className="drawer-section"><div className="drawer-section-title"><span>02</span><strong>Live sources</strong><b className="ready">Verified before AI</b></div><div className="drawer-sources"><label><input type="checkbox" checked={sources.kbase} onChange={(e) => setSources({ ...sources, kbase: e.target.checked })} /><span>Kbase project frame</span><b>{Object.values(state).flat().length} records</b></label><label><input type="checkbox" checked={sources.obsidian} onChange={(e) => setSources({ ...sources, obsidian: e.target.checked })} /><span>Obsidian notes</span><b>Live search</b></label><label><input type="checkbox" checked={sources.zotero} onChange={(e) => setSources({ ...sources, zotero: e.target.checked })} /><span>Zotero literature</span><b>Live search</b></label></div></div>{error && <div className="workflow-error"><span>!</span><p>{error}</p><button onClick={openConnections}>Connections</button></div>}{result && <section className="workflow-result"><div className="workflow-result-head"><span><b>{result.provider}</b><small>{result.model} · Zotero {result.retrieval.zotero.status} · Obsidian {result.retrieval.obsidian.status}</small></span><button onClick={save}>{savedPath ? "Saved ✓" : "Save with evidence"}</button></div>{result.invalidCitations.length > 0 && <div className="citation-warning">Unverified citation IDs: {result.invalidCitations.join(", ")}</div>}<pre>{result.output}</pre><details className="evidence-manifest"><summary>Evidence manifest · {result.manifest.zotero.length + result.manifest.obsidian.length} sources</summary>{result.manifest.zotero.map((item) => <p key={item.id}><b>[{item.id}]</b> {item.title} · Zotero {item.key}</p>)}{result.manifest.obsidian.map((item) => <p key={item.id}><b>[{item.id}]</b> {item.title} · {item.path}</p>)}</details></section>}<div className="drawer-footer"><div><SourceDot /><span><strong>Traceable-source workflow</strong><small>{provider === "kimi" ? "Kimi K3" : "DeepSeek V4 Flash"}</small></span></div><button className="primary-button" disabled={running || !input.trim()} onClick={run}>{running ? "Working…" : result ? "Run again" : "Run workflow"}</button></div></aside></div>;
}

function ConnectionsDrawer({ status, refresh, onClose }: { status: BridgeStatus | null; refresh: () => Promise<void>; onClose: () => void }) {
  const [token, setToken] = useState(""); const [pairingError, setPairingError] = useState("");
  const connection = (connected?: boolean) => <b className={`connection-state ${connected ? "connected" : "missing"}`}>{connected ? "Connected" : "Setup needed"}</b>;
  const pair = async () => { const clean = token.trim(); if (!clean) { setPairingError("Paste the token from the local pairing page."); return; } window.localStorage.setItem("workbuddy-bridge-token", clean); setPairingError(""); await refresh(); window.location.reload(); };
  return <div className="drawer-backdrop" onMouseDown={onClose}><aside className="action-drawer connections-drawer" role="dialog" aria-modal="true" aria-label="Connections" tabIndex={-1} onMouseDown={(e) => e.stopPropagation()}><div className="drawer-head"><button onClick={onClose}>×</button><span className="label">CONNECTIONS</span><span className="action-mark mint">⌁</span></div><div className="drawer-title"><span>LOCAL RESEARCH BRIDGE</span><h2>Real tools, private context.</h2><p>The private pairing token prevents other websites from using your local research systems.</p></div>{!status && <div className="pairing-card"><b>Pair this browser</b><p>Open the local pairing page, copy its token, then paste it below.</p><button onClick={() => window.open(`${BRIDGE_URL}/pair`, "_blank", "noopener,noreferrer")}>Open local pairing page</button><label><span>Bridge token</span><input type="password" autoComplete="off" value={token} onChange={(event) => setToken(event.target.value)} placeholder="Paste local token" /></label><button className="primary-button" onClick={pair}>Pair bridge</button>{pairingError && <small>{pairingError}</small>}</div>}<div className={`bridge-banner ${status ? "online" : "offline"}`}><span>{status ? "✓" : "!"}</span><div><strong>{status ? "Research bridge is paired" : "Bridge pairing required"}</strong><small>Listening only on this Mac</small></div><button onClick={refresh}>Test again</button></div><div className="connection-list"><article><span className="connection-logo deepseek">DS</span><div><strong>DeepSeek API</strong><small>{status?.deepseek.model || "V4 Flash"}</small></div>{connection(status?.deepseek.configured)}</article><article><span className="connection-logo kimi">KM</span><div><strong>Kimi API</strong><small>{status?.kimi.model || "K3"}</small></div>{connection(status?.kimi.configured)}</article><article><span className="connection-logo calendar">C</span><div><strong>macOS Calendar</strong><small>Today · read + write</small></div>{connection(status?.calendar.connected)}</article><article><span className="connection-logo zotero">Z</span><div><strong>Zotero Desktop</strong><small>{status?.zotero.version || "Local API"}</small></div>{connection(status?.zotero.connected)}</article><article><span className="connection-logo obsidian">O</span><div><strong>Obsidian · {status?.obsidian.vault || "Kbase"}</strong><small>Markdown records</small></div>{connection(status?.obsidian.connected)}</article></div></aside></div>;
}

function GuideDrawer({ onClose, openConnections }: { onClose: () => void; openConnections: () => void }) {
  const modules = [
    ["Today", "Choose one concrete output, start a focus session, see today’s schedule, and respond only to submission alerts that need attention."],
    ["Projects", "Manage projects, research questions, and experiments together instead of switching between separate modules."],
    ["Manuscripts", "Track writing plus every submission attempt, status event, revision round, portal link, expected response, and follow-up date."],
    ["Library", "Search Zotero and maintain a deliberate reading queue."],
    ["Review", "Resolve reviewer concerns, research debt, and PhD operational commitments."],
  ];
  return <div className="drawer-backdrop" onMouseDown={onClose}><aside className="action-drawer guide-drawer" onMouseDown={(event) => event.stopPropagation()} aria-label="WorkBuddy user guide">
    <div className="drawer-head"><button onClick={onClose}>×</button><span className="label">USER GUIDE</span><span className="action-mark mint">?</span></div>
    <div className="drawer-title"><span>WORKBUDDY / SPORTS RESEARCH OS</span><h2>How to use your workbench</h2><p>A practical guide to the daily workflow, real data sources, editing, and AI tools.</p></div>
    <nav className="guide-jump" aria-label="Guide sections"><a href="#guide-start">Start here</a><a href="#guide-daily">Daily routine</a><a href="#guide-modules">Modules</a><a href="#guide-ai">AI</a><a href="#guide-storage">Data</a><a href="#guide-help">Help</a></nav>
    <section className="guide-section" id="guide-start"><span className="guide-number">01</span><div><h3>Start here</h3><ol className="guide-steps"><li><b>Define today’s output.</b><span>Add one concrete result on Today and start focused work immediately.</span></li><li><b>Create the research frame.</b><span>In Projects, add the active project, its questions, and related experiments.</span></li><li><b>Add the manuscript.</b><span>Track writing first, then create a separate submission attempt for each journal.</span></li><li><b>Connect sources when useful.</b><span>Zotero, Obsidian, Calendar, AI, and Mail enrich the workflow but no longer block Today.</span></li></ol><button className="quiet-button" onClick={() => { onClose(); openConnections(); }}>Open Connections →</button></div></section>
    <section className="guide-section" id="guide-daily"><span className="guide-number">02</span><div><h3>A simple daily routine</h3><div className="guide-routine"><p><b>1 · Decide</b><span>Choose one visible result worth finishing today.</span></p><p><b>2 · Focus</b><span>Start the linked timer without switching to another module.</span></p><p><b>3 · Record</b><span>Update the project or manuscript with what actually changed.</span></p><p><b>4 · Watch</b><span>Handle a submission alert only when Today says attention is needed.</span></p><p><b>5 · Continue</b><span>Leave the next concrete output ready for tomorrow.</span></p></div></div></section>
    <section className="guide-section" id="guide-modules"><span className="guide-number">03</span><div><h3>What each module is for</h3><div className="guide-module-list">{modules.map(([name, description]) => <article key={name}><b>{name}</b><p>{description}</p></article>)}</div><div className="guide-callout"><b>Editing rule</b><p>Use New to create a record. Open an existing card or row to edit it. Progress is manual and remains authoritative until you change it. Delete requires a second confirmation.</p></div></div></section>
    <section className="guide-section" id="guide-ai"><span className="guide-number">04</span><div><h3>Using AI workflows</h3><ol className="guide-steps"><li><b>Open the workflow menu.</b><span>Use the top search bar or press <kbd>⌘ K</kbd>.</span></li><li><b>Choose a structured task.</b><span>Examples include finding evidence, explaining a result, reviewing a section, and drafting text.</span></li><li><b>Select the model.</b><span>Choose DeepSeek or Kimi inside the workflow panel.</span></li><li><b>Check sources.</b><span>Keep Zotero and Obsidian enabled when the task needs evidence or project context.</span></li><li><b>Review before saving.</b><span>AI output is a draft. Check claims and citations, then save useful results to Obsidian.</span></li></ol><div className="guide-callout warning"><b>Important</b><p>WorkBuddy reports missing context instead of inventing it. AI output still requires your scientific judgment and source verification.</p></div></div></section>
    <section className="guide-section" id="guide-storage"><span className="guide-number">05</span><div><h3>Where your data lives</h3><div className="guide-data"><p><b>Research records</b><span>Readable Markdown files in Obsidian → Kbase → WorkBuddy.</span></p><p><b>Tasks and focus timer</b><span>Stored locally in this browser on this device.</span></p><p><b>Schedule</b><span>Read from and written to macOS Calendar.</span></p><p><b>Literature</b><span>Read live from Zotero Desktop. Queue selections are saved as Kbase records.</span></p><p><b>AI credentials</b><span>Kept by the local bridge on this Mac, never entered into the hosted page.</span></p></div></div></section>
    <section className="guide-section" id="guide-help"><span className="guide-number">06</span><div><h3>Quick troubleshooting</h3><div className="guide-help"><p><b>“Bridge offline”</b><span>Open Connections and use Test again. The local bridge must be running on this Mac.</span></p><p><b>No Zotero literature</b><span>Keep Zotero Desktop open, clear overly narrow search terms, or add project keywords.</span></p><p><b>Dashboard looks empty</b><span>This is expected until you create real project, manuscript, or research-debt records.</span></p><p><b>AI lacks context</b><span>Create an Active project and research question, then add clear descriptions and retrieval keywords.</span></p></div></div></section>
    <div className="drawer-footer guide-footer"><span className="small-note">Press ⌘ K anytime to run an AI workflow</span><button className="primary-button" onClick={onClose}>Done</button></div>
  </aside></div>;
}

export default function Home() {
  const [active, setActive] = useState<ModuleKey>("dashboard"); const [state, setState] = useState<WorkbenchState>(emptyState); const [loading, setLoading] = useState(true); const [dataError, setDataError] = useState("");
  const [editor, setEditor] = useState<EditorState>(null); const [action, setAction] = useState<Action | null>(null); const [status, setStatus] = useState<BridgeStatus | null>(null); const [contextOpen, setContextOpen] = useState(false); const [connectionsOpen, setConnectionsOpen] = useState(false); const [guideOpen, setGuideOpen] = useState(false); const [mobileNav, setMobileNav] = useState(false); const [commandOpen, setCommandOpen] = useState(false); const [query, setQuery] = useState(""); const [toast, setToast] = useState("");
  const loadState = async () => { setLoading(true); setDataError(""); try { const response = await bridgeFetch(`/workbench/state`); const body = await response.json(); if (!response.ok) throw new Error(body.error); setState({ ...emptyState, ...body }); } catch (e) { setDataError(e instanceof Error ? e.message : "Kbase data could not be loaded."); } finally { setLoading(false); } };
  const loadStatus = async () => { try { const response = await bridgeFetch(`/health`, { signal: AbortSignal.timeout(5000) }); setStatus(response.ok ? await response.json() : null); } catch { setStatus(null); } };
  useEffect(() => { const start = window.setTimeout(() => { void loadState(); void loadStatus(); }, 0); const timer = window.setInterval(() => { void loadState(); void loadStatus(); }, 60000); return () => { window.clearTimeout(start); window.clearInterval(timer); }; }, []);
  useEffect(() => { const onKey = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(true); } if (event.key === "Escape") { setCommandOpen(false); setEditor(null); setAction(null); setContextOpen(false); setConnectionsOpen(false); setGuideOpen(false); } }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); }, []);
  useEffect(() => { const requirePairing = () => setToast("Local research sources are offline — Today remains available."); window.addEventListener("workbuddy-pairing-required", requirePairing); return () => window.removeEventListener("workbuddy-pairing-required", requirePairing); }, []);
  useEffect(() => {
    const open = Boolean(editor || action || contextOpen || connectionsOpen || guideOpen || commandOpen); if (!open) return;
    const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null; const shell = document.querySelector<HTMLElement>(".main-shell"); const sidebar = document.querySelector<HTMLElement>(".sidebar"); if (shell) shell.inert = true; if (sidebar) sidebar.inert = true;
    const frame = window.requestAnimationFrame(() => { const dialog = document.querySelector<HTMLElement>(".action-drawer, .command-palette"); if (!dialog) return; dialog.setAttribute("role", "dialog"); dialog.setAttribute("aria-modal", "true"); if (!dialog.hasAttribute("aria-label") && !dialog.hasAttribute("aria-labelledby")) dialog.setAttribute("aria-label", "WorkBuddy panel"); dialog.tabIndex = -1; const autofocus = dialog.querySelector<HTMLElement>("[autofocus], button, input, textarea, select, [href]"); (autofocus || dialog).focus(); });
    const trap = (event: KeyboardEvent) => { if (event.key !== "Tab") return; const dialog = document.querySelector<HTMLElement>(".action-drawer, .command-palette"); if (!dialog) return; const focusable = [...dialog.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), [href], [tabindex]:not([tabindex="-1"])')].filter((item) => !item.hidden); if (!focusable.length) { event.preventDefault(); dialog.focus(); return; } const first = focusable[0]; const last = focusable[focusable.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } };
    document.addEventListener("keydown", trap); return () => { window.cancelAnimationFrame(frame); document.removeEventListener("keydown", trap); if (shell) shell.inert = false; if (sidebar) sidebar.inert = false; previous?.focus(); };
  }, [action, commandOpen, connectionsOpen, contextOpen, editor, guideOpen]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(""), 2400); return () => window.clearTimeout(timer); }, [toast]);
  const saveRecord = async (collection: CollectionKey, record: Partial<RecordItem>) => { const response = await bridgeFetch(`/workbench/record`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ collection, record }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error || "Record could not be saved."); await loadState(); setToast(`${collectionLabels[collection]} saved to Kbase`); };
  const deleteRecord = async (collection: CollectionKey, id: string) => { const response = await bridgeFetch(`/workbench/record`, { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ collection, id }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error || "Record could not be deleted."); await loadState(); setToast(`${collectionLabels[collection]} deleted`); };
  const addSubmissionEvent = async (record: Partial<RecordItem>) => { const response = await bridgeFetch(`/submissions/event`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(record) }); const body = await response.json(); if (!response.ok) throw new Error(body.error || "Submission event could not be saved."); await loadState(); setToast("Submission timeline updated"); };
  const syncSubmissionEmail = async () => { const response = await bridgeFetch(`/submissions/email-sync`, { method: "POST", headers: { "Content-Type": "application/json" }, body: "{}", signal: AbortSignal.timeout(40000) }); const body = await response.json(); if (!response.ok) throw new Error(body.error || "Mail could not be checked."); await loadState(); return body as SubmissionSyncResult; };
  const openEditor = (collection: CollectionKey, record?: RecordItem) => setEditor({ collection, record }); const activeLabel = navItems.find((item) => item.key === active)?.label || "Today";
  const badges: Partial<Record<ModuleKey, number>> = { manuscript: submissionAlerts(state).length || state.manuscripts.length, review: state.reviews.filter((item) => item.status !== "Resolved").length + state["research-debt"].filter((item) => item.status !== "Resolved").length, projects: state.projects.length, library: state["reading-queue"].length };
  const commands = useMemo(() => quickActions.filter((item) => `${item.label} ${item.meta} ${item.command}`.toLowerCase().includes(query.toLowerCase())), [query]);
  const props: DataProps = { state, openEditor, saveRecord, runAction: setAction };
  return <div className="app-shell"><aside className={`sidebar ${mobileNav ? "mobile-open" : ""}`}><div className="brand"><span className="brand-mark"><i /><b /></span><span><strong>WORKBUDDY</strong><small>SPORTS RESEARCH OS</small></span><button className="mobile-close" onClick={() => setMobileNav(false)}>×</button></div><nav><span className="nav-label">RESEARCH WORKBENCH</span>{navItems.map((item) => <button key={item.key} className={active === item.key ? "active" : ""} onClick={() => { setActive(item.key); setMobileNav(false); window.scrollTo({ top: 0, behavior: "smooth" }); }}><span className="nav-icon">{item.icon}</span><span>{item.label}</span>{Boolean(badges[item.key]) && <b>{badges[item.key]}</b>}</button>)}</nav><div className="sidebar-bottom"><button onClick={() => { setGuideOpen(true); setMobileNav(false); }}><span className="nav-icon">?</span><span>User Guide</span></button><button onClick={() => setConnectionsOpen(true)}><span className="nav-icon">⚙</span><span>Connections</span></button><div className={`sync-status ${status ? "" : "offline"}`}><span className="sync-orbit"><i /><b /></span><span><strong>Research systems</strong><small><SourceDot tone={status ? "green" : "orange"} />{status ? "Local bridge connected" : "Bridge offline · Today still works"}</small></span></div></div></aside><div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="mobile-menu" onClick={() => setMobileNav(true)}>☰</button><span>Research Workbench</span><b>/</b><strong>{activeLabel}</strong></div><button className="command-trigger" onClick={() => setCommandOpen(true)}><span>⌕</span><span>Search or run an AI assist…</span><kbd>⌘ K</kbd></button><div className="top-actions"><button className="icon-button" onClick={() => { void loadState(); void loadStatus(); setToast("Refreshing real data"); }}>↻</button><button className="context-button" onClick={() => setContextOpen(true)}><span className="context-diamond">◇</span><span><small>CONTEXT</small><strong>{Object.values(state).flat().length} real records</strong></span></button><button className="profile-button" onClick={() => setConnectionsOpen(true)}>DR</button></div></header><main className="content">{dataError && <div className="data-banner compact-banner"><span>!</span><p>{dataError} Today’s local focus tools remain available.</p><button onClick={loadState}>Retry</button></div>}{loading && !Object.values(state).flat().length && <div className="loading-bar"><i />Loading Kbase records…</div>}{active === "dashboard" && <Dashboard {...props} openContext={() => setContextOpen(true)} openManuscripts={() => setActive("manuscript")} />}{active === "projects" && <ProjectsModule state={state} openEditor={openEditor} />}{active === "manuscript" && <ManuscriptModule state={state} openEditor={openEditor} addEvent={addSubmissionEvent} syncEmail={syncSubmissionEmail} />}{active === "library" && <LibraryModule state={state} saveRecord={saveRecord} openEditor={openEditor} />}{active === "review" && <ReviewModule state={state} openEditor={openEditor} />}</main></div>{editor && <RecordEditor key={`${editor.collection}-${editor.record?.id || "new"}`} editor={editor} onClose={() => setEditor(null)} onSave={saveRecord} onDelete={deleteRecord} />}{action && <ActionDrawer action={action} state={state} onClose={() => setAction(null)} openConnections={() => setConnectionsOpen(true)} />}{contextOpen && <ContextDrawer state={state} status={status} onClose={() => setContextOpen(false)} />}{connectionsOpen && <ConnectionsDrawer status={status} refresh={loadStatus} onClose={() => setConnectionsOpen(false)} />}{guideOpen && <GuideDrawer onClose={() => setGuideOpen(false)} openConnections={() => setConnectionsOpen(true)} />}{commandOpen && <div className="command-backdrop" onMouseDown={() => setCommandOpen(false)}><div className="command-palette" onMouseDown={(e) => e.stopPropagation()}><div className="command-search"><span>⌕</span><input autoFocus value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search AI assists…" /><kbd>ESC</kbd></div><div className="command-results"><span className="label">CONTEXTUAL AI ASSISTS</span>{commands.map((item) => <button key={item.command} onClick={() => { setAction(item); setCommandOpen(false); setQuery(""); }}><span className={`action-mark ${item.tone}`}>✦</span><span><strong>{item.label}</strong><small>{item.command}</small></span><b>{item.meta}</b></button>)}</div></div></div>}{toast && <div className="toast"><span>✓</span>{toast}</div>}</div>;
}
